CREATE TABLE IF NOT EXISTS users (id TEXT PRIMARY KEY, name TEXT NOT NULL, email TEXT NOT NULL UNIQUE, phone TEXT, role_id TEXT, status TEXT NOT NULL DEFAULT 'active', created_at TEXT NOT NULL DEFAULT CURRENT_TIMESTAMP, updated_at TEXT NOT NULL DEFAULT CURRENT_TIMESTAMP);
CREATE TABLE IF NOT EXISTS roles (id TEXT PRIMARY KEY, name TEXT NOT NULL UNIQUE, description TEXT, status TEXT NOT NULL DEFAULT 'active');
CREATE TABLE IF NOT EXISTS permissions (id TEXT PRIMARY KEY, name TEXT NOT NULL UNIQUE, description TEXT);
CREATE TABLE IF NOT EXISTS role_permissions (role_id TEXT NOT NULL REFERENCES roles(id), permission_id TEXT NOT NULL REFERENCES permissions(id), PRIMARY KEY(role_id, permission_id));
CREATE TABLE IF NOT EXISTS audit_logs (id TEXT PRIMARY KEY, user_id TEXT, action TEXT NOT NULL, entity_type TEXT NOT NULL, entity_id TEXT NOT NULL, before_data TEXT, after_data TEXT, ip_address TEXT, user_agent TEXT, created_at TEXT NOT NULL DEFAULT CURRENT_TIMESTAMP);
INSERT OR IGNORE INTO roles (id,name,description) VALUES ('role-super-admin','SUPER_ADMIN','Akses penuh konfigurasi dan audit'),('role-admin','ADMIN','Operasional dan master data'),('role-kasir','KASIR','Transaksi POS dan member'),('role-pegawai','PEGAWAI','Akses operasional terbatas');
INSERT OR IGNORE INTO permissions (id,name,description) VALUES ('perm-dashboard','dashboard.view','Melihat dashboard'),('perm-member','member.manage','Mengelola member'),('perm-master','master.manage','Mengelola master data'),('perm-pos','transaction.create','Membuat transaksi POS'),('perm-wallet','wallet.manage','Mengelola deposit dan saldo'),('perm-point','point.manage','Mengelola point'),('perm-report','report.view','Melihat laporan'),('perm-role','role.manage','Mengelola role dan permission');
INSERT OR IGNORE INTO role_permissions (role_id,permission_id) SELECT 'role-super-admin',id FROM permissions;
INSERT OR IGNORE INTO role_permissions (role_id,permission_id) SELECT 'role-admin',id FROM permissions WHERE name IN ('dashboard.view','member.manage','master.manage','transaction.create','wallet.manage','point.manage','report.view');
INSERT OR IGNORE INTO role_permissions (role_id,permission_id) SELECT 'role-kasir',id FROM permissions WHERE name IN ('dashboard.view','member.manage','transaction.create');
